import React from "react";

import { cn } from "@/lib/utils";

/**
 * Full-colour brand marks for the toolkit chips, keyed on the exact label in
 * `lib/stack.ts`.
 *
 * The paths are lifted from tech-stack-icons (MIT) rather than depending on it.
 * That package keeps all 691 icons in a single object its component indexes into,
 * so a bundler can't drop the ones you don't use — importing one icon ships ~2.6 MB
 * gzipped. Twenty marks inlined here cost a few KB.
 *
 * Two deliberate swaps from the upstream data:
 *   - Marks that are flat black upstream (Motion, Expo, Prisma, Vercel, and the
 *     Next.js disc) are drawn in `currentColor`, with the Next.js knockout in
 *     `var(--background)`. Upstream ships a separate white-on-dark copy of each;
 *     letting the theme drive them means one copy covers both.
 *   - Clip paths that only clipped to the viewBox are dropped, and every surviving
 *     id is namespaced. SVG ids are document-global and upstream reuses "a"/"b"/"c"
 *     across icons, so twenty marks on one page would otherwise collide.
 *
 * GitHub Actions comes from Simple Icons instead — tech-stack-icons has no entry —
 * scaled from its 24-unit grid and filled with the official brand hex.
 *
 * NativeWind has no mark in either set, so it falls back to a dot. Better a dot
 * than Tailwind's logo standing in for something that isn't Tailwind.
 */
/**
 * Marks that carry internal ids are functions of a suffix. SVG ids are global to
 * the document, so a mark rendered twice on a page — as the hover roll does — needs
 * its second copy's gradients renamed or both copies resolve to the first one's.
 */
type Mark = React.ReactElement | ((uid: string) => React.ReactElement);

