export function BrandIcon({
  name,
  uid = "",
  className,
}: {
  name: string;
  /** Distinguishes the ids of two copies of the same mark on one page. */
  uid?: string;
  className?: string;
}) {
  const mark = MARKS[name];

  if (!mark) {
    return (
      <span
        aria-hidden
        className={cn("inline-flex size-3.5 shrink-0 items-center justify-center", className)}
      >
        <span className="size-1 rounded-full bg-current opacity-40" />
      </span>
    );
  }

  return (
    <svg
      aria-hidden
      viewBox="0 0 100 100"
      fill="none"
      className={cn("size-3.5 shrink-0", className)}
    >
      {typeof mark === "function" ? mark(uid) : mark}
    </svg>
  );
}
